static void clar_release_FpCapture(clar_rec_FpCapture *r) {
    if (rt_list_lastref(r->cv_stmts)) { int32_t i; for (i = 0; i < rt_list_count(r->cv_stmts); i++) clar_fn_rtTextRelease((void*)*(rt_text **)rt_list_at(r->cv_stmts, i)); }
    rt_list_release(r->cv_stmts);
    clar_fn_rtTextRelease((void*)r->cv_value);

}


