static int32_t clar_fn_findIRFuncIdxByName(int32_t cv_nameIdx) {
    int32_t cv_i;
    cv_i = 0;
    cv_i = 0;
    while (1) {
        if (!((cv_i < clar_fn_rtListCount((void*)cv_irFuncs)))) break;
        if (clar_fn_irFuncName(cv_i) == cv_nameIdx) {
            return cv_i;
        }
        cv_i = (cv_i + 1);
    }
    return (-(1));
    return 0;
}

